import{_ as t,C as n,o as r,c as e,j as i,E as l,a as s,a3 as d}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"11-sinf","link":"/11-sinf/"},"n":2,"bob":"I-bob · Dasturiy ta'minot ishlab chiqish asoslari","lessons":[{"g":4,"title":"Git branching strategiyalari va Conventional Commits","lead":"Bir vaqtning o'zida yuzlab muhandislar bitta loyihada bir-biriga xalaqit bermasdan qanday ishlaydi? Nega professional dasturchilar commit xabarlariga \\"ishladi\\" deb emas, qat'iy xalqaro standartda yozishadi? Ushbu darsda Git tarmoqlanish arxitekturasi va Conventional Commits madaniyatini o'rganamiz.","link":"/11-sinf/hafta-02/dars-1","slide":"/slaydlar/11-sinf/hafta-02/dars-1.html","test":"/slaydlar/11-sinf/hafta-02/dars-1-test.html"},{"g":5,"title":"Pull Request (PR) madaniyati, PR shabloni va Merge konfliktlar","lead":"Kod yozish — ishning bor-yo'g'i yarmi. Uni jamoaga to'g'ri taqdim etish, tushuntirish va xatolarsiz asosiy tarmoqqa birlashtirish haqiqiy muhandislik mahoratidir. Ushbu darsda professional Pull Request (PR) ochish, PR shablonlari, merge turlari va qo'rqinchli ko'ringan Merge Konfliktlarni oson hal qilishni o'rganamiz.","link":"/11-sinf/hafta-02/dars-2","slide":"/slaydlar/11-sinf/hafta-02/dars-2.html","test":"/slaydlar/11-sinf/hafta-02/dars-2-test.html"},{"g":6,"title":"Code Review metodologiyasi, etikasi va Branch Protection","lead":"Eng zo'r kod — bu bir kishi yozgan, lekin butun jamoaning aqli bilan sayqallangan koddir. Code Review nafaqat xatolarni ushlaydi, balki dasturchini tezroq o'stiradi. Ushbu darsda professional muloqot etikasi, \\"Nitpick vs Blocker\\", GitHub taklif kodi va asosiy tarmoqni qulflash (Branch Protection)ni o'rganamiz.","link":"/11-sinf/hafta-02/dars-3","slide":"/slaydlar/11-sinf/hafta-02/dars-3.html","test":"/slaydlar/11-sinf/hafta-02/dars-3-test.html"}],"test":"/slaydlar/11-sinf/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"11-sinf/hafta-02/index.md","filePath":"11-sinf/hafta-02/index.md"}`),h={name:"11-sinf/hafta-02/index.md"},g={class:"blk"},c={id:"uyga-vazifa",tabindex:"-1"};function u(m,a,f,b,q,k){const o=n("Icon");return r(),e("div",null,[i("div",g,[i("h2",c,[l(o,{name:"house"}),a[0]||(a[0]=s(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Parol, shaxsiy token, maxfiy kalit va shaxsiy ma&#39;lumotlarni repozitoriyga yozmang: topshirishda faqat ochiq GitHub repo yoki Pull Request havolasi kerak.</p><h3 id="_4-dars-uchun-branching-va-conventional-commits" tabindex="-1">4-dars uchun (Branching va Conventional Commits) <a class="header-anchor" href="#_4-dars-uchun-branching-va-conventional-commits" aria-label="Permalink to &quot;4-dars uchun (Branching va Conventional Commits)&quot;">​</a></h3><p><strong>1-topshiriq: «GitHub Flow va Semantik commitlar»</strong></p><ol><li>O&#39;z portfolio repozitoriyangizda <code>feature/user-profile</code> nomli yangi tarmoq oching.</li><li>Kamida 3 ta mustaqil commit qiling. Commit xabarlari qat&#39;iy <strong>Conventional Commits</strong> spetsifikatsiyasi asosida bo&#39;lsin: <ul><li><code>feat(profile): add avatar upload and bio field</code></li><li><code>fix(profile): validate image file format and max size</code></li><li><code>docs(readme): document profile setup and requirements</code></li></ul></li><li>Terminalda <code>git log --oneline --graph</code> buyrug&#39;ini ishga tushiring va xabarlar aniq, semantik tartibda chiqqanini tekshiring.</li><li>Ushbu branch&#39;ni GitHub&#39;ga push qiling (<code>git push -u origin feature/user-profile</code>).</li></ol><p><strong>Kutiladigan natija:</strong> GitHub&#39;da yangi <code>feature/user-profile</code> tarmog&#39;i mavjud; commit xabarlari standart talablariga to&#39;liq javob beradi.<br><strong>Topshirish:</strong> GitHub tarmog&#39;i havolasi yoki commitlar tarixi skrinshoti.</p><hr><h3 id="_5-dars-uchun-pull-request-va-merge-konfliktlari" tabindex="-1">5-dars uchun (Pull Request va Merge Konfliktlari) <a class="header-anchor" href="#_5-dars-uchun-pull-request-va-merge-konfliktlari" aria-label="Permalink to &quot;5-dars uchun (Pull Request va Merge Konfliktlari)&quot;">​</a></h3><p><strong>2-topshiriq: «Mukammal PR va sun&#39;iy konfliktni yechish»</strong></p><ol><li><code>feature/user-profile</code> tarmog&#39;idan <code>main</code> tarmog&#39;iga qarab rasmiy Pull Request oching.</li><li>PR tavsifini <strong>What / Why / How</strong> professional shabloni bo&#39;yicha to&#39;ldiring: <ul><li><strong>What:</strong> Qanday o&#39;zgarishlar kiritildi?</li><li><strong>Why:</strong> Bu o&#39;zgarish nima uchun kerak (muammo yoki vazifa)?</li><li><strong>How:</strong> Texnik yechim qanday amalga oshirildi?</li><li>Skrinshot yoki test natijasi ilova qiling.</li></ul></li><li>Ataylab merge konflikti hosil qiling: <code>main</code> da ham, <code>feature/user-profile</code> da ham bitta faylning ayni bir qatorini o&#39;zgartirib commit qiling.</li><li>Konflikt belgilarini (<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>, <code>=======</code>, <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>) o&#39;chirib, toza yechimni saqlang va commit qilib PR ni yangilang.</li></ol><p><strong>Kutiladigan natija:</strong> Tavsifi to&#39;liq, skrinshotli, nizosiz (Able to merge) yashil holatdagi Pull Request.<br><strong>Topshirish:</strong> GitHub Pull Request havolasi.</p><hr><h3 id="_6-dars-uchun-code-review-va-branch-protection" tabindex="-1">6-dars uchun (Code Review va Branch Protection) <a class="header-anchor" href="#_6-dars-uchun-code-review-va-branch-protection" aria-label="Permalink to &quot;6-dars uchun (Code Review va Branch Protection)&quot;">​</a></h3><p><strong>3-topshiriq: «Branch Protection va Taklif kodi»</strong></p><ol><li>Repozitoriyangiz sozlamalariga kiring (<code>Settings → Branches</code>) va <code>main</code> tarmog&#39;i uchun himoya qoidasini yoqing: <ul><li><code>Require a pull request before merging</code> (to&#39;g&#39;ridan-to&#39;g&#39;ri push taqiqlansin);</li><li><code>Require approvals: 1</code> (kamida 1 ta tasdiq talab qilinsin).</li></ul></li><li>Terminalda <code>main</code> tarmog&#39;ida turib to&#39;g&#39;ridan-to&#39;g&#39;ri push qilib ko&#39;ring va <code>GH006: Protected branch</code> xatoligini oling.</li><li>Do&#39;stingiz (yoki mentor) ochgan PR ga kiring: <ul><li>Kod diff&#39;idan bitta qatorni tanlab inline sharh qoldiring;</li><li>Kamida 1 ta <code>suggestion</code> bloki orqali to&#39;g&#39;rilangan kod taklifini taqdim eting;</li><li>Agar xatolik bo&#39;lmasa <code>Approve</code>, aks holda <code>Request changes</code> tugmasini bosing.</li></ul></li></ol><p><strong>Kutiladigan natija:</strong> <code>main</code> tarmog&#39;i himoyalangan, to&#39;g&#39;ridan-to&#39;g&#39;ri push bloklanadi; PR sahifasida konstruktiv inline sharh va bir bosishda qabul qilinuvchi code suggestion mavjud.<br><strong>Topshirish:</strong> Sozlangan Branch Protection sahifasi skrinshoti va yozilgan review/suggestion havolasi (yoki skrinshoti).</p><hr>',16))])])}const y=t(h,[["render",u]]);export{p as __pageData,y as default};
